(function(){
  function parse(text){
    var blocks=String(text||'').split(/\n\s*\n/), entries=[];
    for(var i=0;i<blocks.length;i++){
      var b=blocks[i].trim(); if(!b)continue;
      var lines=b.split(/\r?\n/);
      var first=lines[0].trim().match(/^(GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS)\s+(\S+)/i);
      if(!first) continue;
      var e={method:first[1].toUpperCase(), url:first[2], headers:{}, body:'', asserts:[]};
      for(var j=1;j<lines.length;j++){ var ln=lines[j].trim(); if(!ln)continue;
        var sm=ln.match(/^(GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS)\s+/i); if(sm) break;
        var hm=ln.match(/^([\w-]+):\s*(.+)$/);
        if(hm && !/^(HTTP|status|body|header)$/i.test(hm[1])){ e.headers[hm[1]]=hm[2]; continue; }
        var am=ln.match(/(?:status|HTTP\/\d\.\d)\s*(==|!=|>=|<=|>|<)\s*(\d+)/i);
        if(am){ e.asserts.push({kind:'status', op:am[1], val:+am[2]}); continue; }
        var bm=ln.match(/^body\s+(contains|matches|==)\s+(.+)$/i);
        if(bm){ e.asserts.push({kind:'body', op:bm[1].toLowerCase(), val:bm[2]}); continue; }
        if(/^[{\[]/.test(ln)){ e.body+= (e.body?'\n':'')+ln; }
      }
      entries.push(e);
    }
    return {value:entries};
  }
  var API={parse:parse};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__HurlForge__=API;
})();
